  'help.faq.cantLogin.q': 'No puedo acceder a mi cuenta',
  'help.faq.cantLogin.a': 'Verifica que estes usando el correo y contrasena correctos. Si olvidaste tu contrasena, haz clic en "Olvidaste la contrasena?" en la pantalla de inicio de sesión. Si el problema persiste, crea un ticket de soporte.',
  'help.faq.notReceiving.q': 'No estoy recibiendo correos',
  'help.faq.notReceiving.a': 'Revisa tu carpeta de Spam primero. Asegurate de que tu almacenamiento no este lleno. Si el problema continua, verifica que el remitente tenga la direccion correcta y crea un ticket.',
  'help.faq.cantSend.q': 'No puedo enviar correos',
  'help.faq.cantSend.a': 'Verifica tu conexión a internet y que la direccion del destinatario sea correcta. Revisa que los adjuntos no superen los 25MB. Intenta de nuevo en unos minutos.',
  'help.faq.forgotPassword.q': 'Olvide mi contrasena',
  'help.faq.forgotPassword.a': 'En la pantalla de inicio de sesión, haz clic en "Olvidaste la contrasena?" y sigue las instrucciones para restablecer tu contrasena via correo de recuperacion.',
  'help.faq.accountSecurity.q': 'Creo que mi cuenta fue comprometida',
  'help.faq.accountSecurity.a': 'Cambia tu contrasena inmediatamente. Revisa la carpeta Enviados por mensajes que no enviaste. Activa la autenticacion de dos factores en Configuración > Seguridad. Si es necesario, crea un ticket urgente.',
  'help.faq.appAccess.q': 'Como accedo a la app en el celular?',
  'help.faq.appAccess.a': 'Puedes acceder a Chatyy desde cualquier navegador en chatyy.com.br, o descargar nuestra app en la tienda de aplicaciones de tu dispositivo.',

  // Privacy modal
  'privacy.title': 'Politica de Privacidad',
  'privacy.subtitle': 'Como protegemos y manejamos tus datos',
  'privacy.lastUpdated': 'Ultima actualizacion: Marzo 2026',
  'privacy.dataCollection.title': 'Recopilacion de Datos',
  'privacy.dataCollection.body': 'Recopilamos solo la información necesaria para el servicio de correo: tu nombre, direccion de correo y el contenido de los mensajes enviados y recibidos. No vendemos ni compartimos tus datos personales con terceros para fines de marketing.',
  'privacy.dataUsage.title': 'Como Usamos tus Datos',
  'privacy.dataUsage.body': 'Tus datos se usan exclusivamente para operar y mejorar el servicio de correo, incluyendo entrega de mensajes, filtrado de spam, funciones de IA (con tu consentimiento) y seguridad de la cuenta.',
  'privacy.dataSecurity.title': 'Seguridad de Datos',
  'privacy.dataSecurity.body': 'Usamos encriptacion estandar de la industria (TLS/SSL) para todos los datos en transito y en reposo. Las sesiones estan protegidas con tokens encriptados y proteccion CSRF. Auditamos regularmente nuestras practicas de seguridad.',
  'privacy.cookies.title': 'Cookies y Almacenamiento Local',
  'privacy.cookies.body': 'Usamos cookies esenciales y almacenamiento local para mantener tu sesión, recordar tus preferencias (tema, idioma) y brindar una experiencia fluida. No usamos cookies de rastreo de terceros.',
  'privacy.thirdParties.title': 'Servicios de Terceros',
  'privacy.thirdParties.body': 'Podemos usar servicios de terceros para funcionalidades especificas como IA (Anthropic Claude) y notificaciones push. Estos servicios siguen sus propias politicas de privacidad y procesan solo los datos minimos necesarios.',
  'privacy.rights.title': 'Tus Derechos',
  'privacy.rights.body': 'Tienes derecho a acceder, corregir, exportar o eliminar tus datos personales en cualquier momento. Puedes gestionar tus datos en Configuración o contactando a nuestro soporte.',
  'privacy.contact.title': 'Contactanos',
  'privacy.contact.body': 'Para consultas de privacidad o solicitudes de datos, contactanos en privacy@chatyy.com.br. Responderemos en un maximo de 30 días.',

  // Terms modal
  'terms.title': 'Terminos de Servicio',
  'terms.subtitle': 'Directrices de uso de Chatyy',
  'terms.lastUpdated': 'Ultima actualizacion: Marzo 2026',
  'terms.acceptance.title': 'Aceptacion de Terminos',
  'terms.acceptance.body': 'Al acceder o usar Chatyy, aceptas estos Terminos de Servicio. Si no estas de acuerdo con alguna parte de estos terminos, no utilices el servicio.',
  'terms.services.title': 'Descripcion de Servicios',
  'terms.services.body': 'Chatyy proporciona servicios de comunicacion por correo incluyendo envio, recepcion y gestion de correos, ademas de funciones de IA, integracion con calendario y videoconferencia.',
  'terms.accounts.title': 'Cuentas de Usuario',
  'terms.accounts.body': 'Eres responsable de mantener la seguridad de tus credenciales. No compartas tu contrasena ni permitas acceso no autorizado a tu cuenta. Debes tener al menos 13 anos para usar este servicio.',
  'terms.conduct.title': 'Uso Aceptable',
  'terms.conduct.body': 'Aceptas no usar el servicio para enviar spam, malware, phishing o cualquier contenido ilegal. No intentes acceder a cuentas de otros usuarios ni interrumpir la infraestructura del servicio.',
  'terms.content.title': 'Propiedad del Contenido',
  'terms.content.body': 'Conservas la propiedad de todo el contenido que creas y envias a traves del servicio. No reclamamos propiedad sobre tus correos o adjuntos. Podemos procesar el contenido segun sea necesario para proporcionar el servicio.',
  'terms.limitation.title': 'Limitacion de Responsabilidad',
  'terms.limitation.body': 'Chatyy se proporciona "tal cual". Buscamos 99.9% de disponibilidad pero no garantizamos servicio ininterrumpido. No somos responsables por danos indirectos, incidentales o consecuentes derivados del uso del servicio.',
  'terms.termination.title': 'Terminacion de Cuenta',
  'terms.termination.body': 'Podemos suspender o terminar cuentas que violen estos terminos. Puedes eliminar tu cuenta en cualquier momento en Configuración. Tras la terminacion, tus datos se eliminaran en un plazo de 30 días.',
  'terms.changes.title': 'Cambios en los Terminos',
  'terms.changes.body': 'Podemos actualizar estos terminos periodicamente. Te notificaremos sobre cambios significativos por correo o notificación en la app. El uso continuado despues de los cambios constituye aceptacion de los terminos actualizados.',

