  "liveDiag.clearBody": "Borra todos los registros de envío de la transmisión. Úsalo después de informar a soporte.",
  "liveDiag.whatTitle": "¿Qué es esto?",
  "liveDiag.whatBody": "Cuando inicias una transmisión, la app envía tu cámara y micrófono al servidor de streaming, que reparte el video a quienes miran. Si algo falla en ese envío (red, permisos, NAT), los espectadores se quedan en \"Conectando…\". Aquí están los registros del último intento para que tú (o soporte) sepan exactamente dónde se detuvo.",
